/**
 * The shared contract for per-game modding support in Cyrus (PURE, client-safe, data + types only).
 * Every supported game has ONE file `lib/cyrus/games/<gameId>.ts` default-exporting a `GameSupport`.
 * The studio, the install flow, the lifecycle warnings, the mod store and the marketing page all read
 * from it, so a fact is written once. Facts must be VERIFIED against the loader's own docs/source
 * (cite the URL in `sources`), never guessed. Where something could not be confirmed, say so in `unknowns`.
 */

/** Where a mod's files must be installed for it to work. */
export type InstallSide = "server" | "client" | "both";

export type GameVersionRule = {
  /** Game/server build the mod targets, as the loader labels it ("1.21.4", "v0.4.x", "Build 42"). */
  version: string;
  status: "current" | "supported" | "legacy" | "unsupported";
  /** Loader/framework version needed with this game version ("BepInEx 5.4.2200", "Oxide 2.0.x"). */
  loaderVersion?: string;
  /** What changed that breaks mods from the previous version (so we can warn). */
  breaking?: string[];
};

export type DangerousApi = {
  /** Regex source matched against generated code; a hit blocks the build or forces a warning. */
  pattern: string;
  severity: "block" | "warn";
  why: string;
};

export type FailureRule = {
  id: string;
  /** Regex source run against generated code (or, for kind "compiler-warning"/"runtime", against tool output). */
  detect: string;
  /** Hint injected into the repair prompt. */
  fix: string;
  why: string;
  kind?: "source" | "compiler-warning" | "runtime";
  /** Versions this rule applies to (default: the pack's version). */
  versions?: string[];
  /** True when a deterministic rewrite can fix it without a model turn (see services/modbuilder autofix). */
  autofix?: boolean;
};

export type KnowledgePack = { version: string; apiSheet: string[]; failureRules: FailureRule[] };

/** The (first) knowledge pack of a game, whether it declared one pack or several. */
export function packOf(k: KnowledgePack | KnowledgePack[] | undefined): KnowledgePack | undefined {
  return Array.isArray(k) ? k[0] : k;
}

export type GameSupport = {
  id: string;                    // matches CyrusGame.id in lib/cyrus/games.ts
  name: string;
  /** Plain-language one-liner of what Cyrus builds for this game. */
  builds: string;
  /** Language(s) the mod is written in and the runtime that loads it. */
  language: "Java" | "C#" | "Lua" | "C++" | "JSON/data";
  loader: { name: string; homepage: string; installDocs: string; licenseNote?: string };
  versions: GameVersionRule[];
  /** Where it installs. `reason` is shown to the customer in plain words ("players must also install this"). */
  install: {
    side: InstallSide;
    serverPath: string;          // relative to the game server root
    clientNote?: string;         // what a player must do on their own PC, if side is client/both
    needsRestart: boolean;
    hotReload: boolean;
    packaging: "jar" | "cs-source" | "dll" | "zip" | "lua-folder" | "pak";
    reason: string;
  };
  /** How Cyrus verifies output BEFORE the customer sees it. */
  verification: {
    method: "compile" | "static-lint" | "load-test" | "none";
    notes: string;
    /** Can we run it for real in a sandbox here, or only lint? Be honest. */
    canRunSandbox: boolean;
  };
  dangerousApis: DangerousApi[];
  /** Things that commonly break players' games/servers for this title, with how we avoid them. */
  breakageRisks: { risk: string; guard: string }[];
  /** How a mod becomes "out of date": what signal tells us (game patch, loader update, API removal). */
  outdatedSignals: { signal: string; source: string }[];
  /** Mod categories this game's engine can actually express (ids from lib/cyrus/categories.ts universal set). */
  categories: string[];
  /** Concrete example prompts that work well, for the starter chips. */
  examplePrompts: string[];
  /**
   * Per-game, per-version knowledge pack(s) (optional). One pack per game version (an array when a game supports
   * several, e.g. Minecraft 1.21.x), or a single pack. `apiSheet` lines are VERIFIED API facts for `version`
   * (retrieval injects only the lines for the APIs a plan touches); `failureRules` are known ways generated code
   * breaks on that version. Keep game binaries and decompiled output OUT of git: only the distilled facts go here.
   */
  knowledge?: KnowledgePack | KnowledgePack[];
  sources: string[];             // URLs verified while writing this file
  unknowns: string[];            // honest list of anything not confirmed
};
