/**
 * Minecraft (Paper / Purpur server plugins): the one game Cyrus builds for for real today.
 * GameSupport facts for the lifecycle (install, compatibility, health, creator warnings).
 *
 * Written by the lifecycle agent (2026-10-08) because no game agent owns Minecraft. Every
 * version below is one the build service compiles against (lib/modbuilder/types.ts
 * MB_VERSIONS); the newest is "current". Paper's own list (fill.papermc.io, read 2026-10-08)
 * already has 26.1, 26.2 and 26.3, which Cyrus CANNOT build for yet: a server on 26.x is
 * "newer than Cyrus has tested", which the lifecycle shows as Outdated + a creator warning,
 * never as a block (a 1.21 plugin may well still load, we just haven't proved it).
 */
import type { GameSupport } from "./support";

const minecraft: GameSupport = {
  id: "minecraft",
  name: "Minecraft",
  builds: "Paper and Purpur server plugins",
  language: "Java",
  loader: {
    name: "Paper",
    homepage: "https://papermc.io/",
    installDocs: "https://docs.papermc.io/paper/adding-plugins",
  },
  versions: [
    { version: "1.21.11", status: "current", loaderVersion: "Paper 1.21.11 (Java 21)" },
    { version: "1.21.8", status: "supported", loaderVersion: "Paper 1.21.8 (Java 21)" },
    { version: "1.21.4", status: "supported", loaderVersion: "Paper 1.21.4 (Java 21)" },
    { version: "1.21.1", status: "legacy", loaderVersion: "Paper 1.21.1 (Java 21)" },
    {
      version: "1.20.x",
      status: "unsupported",
      breaking: ["Cyrus compiles against the 1.21 Paper API; methods and registries it uses may not exist on 1.20.x."],
    },
    { version: "1.19.x", status: "unsupported" },
    { version: "1.18.x", status: "unsupported" },
    { version: "1.17.x", status: "unsupported" },
    { version: "1.16.x", status: "unsupported" },
  ],
  install: {
    side: "server",
    serverPath: "plugins/",
    needsRestart: true,
    hotReload: false,
    packaging: "jar",
    reason: "This is a server plugin: it runs only on your server. Players join with a normal, unmodded Minecraft, nothing to install on their PC.",
  },
  verification: {
    method: "compile",
    notes: "The build service compiles every version against the Paper API for the chosen Minecraft version and runs a static safety scan before the jar is offered.",
    canRunSandbox: false,
  },
  dangerousApis: [
    { pattern: "Runtime\\.getRuntime\\(\\)\\.exec|ProcessBuilder", severity: "block", why: "Starting processes on the host is never needed by a gameplay plugin." },
    { pattern: "System\\.exit\\(", severity: "block", why: "Stops the whole server." },
  ],
  breakageRisks: [
    { risk: "A plugin built for one Minecraft version loaded on a much newer one can fail to enable (missing methods).", guard: "Version check before install; Outdated badge + creator warning when the server is newer than the mod was built for." },
    { risk: "Two copies of the same plugin in plugins/ (an old manual upload and a new install).", guard: "The engine adopts and backs up older Nxeon copies before placing the new jar (lib/modbuilder/install.ts)." },
    { risk: "Using /reload to load a new jar leaves plugins half-initialised.", guard: "We never hot-reload; a restart loads the change." },
  ],
  outdatedSignals: [
    { signal: "The server runs a newer Minecraft version than any version of the mod was built for.", source: "server config VERSION / the version line in the server log" },
    { signal: "Cyrus can build for a newer Minecraft version than the mod's newest build.", source: "this file's `versions` (current)" },
    { signal: "Paper logs `Could not load 'plugins/<jar>'` or `Error occurred while enabling <Plugin>` after a version change.", source: "game log (lib/cyrus/lifecycle/logs.ts)" },
  ],
  categories: [],
  examplePrompts: [
    "A coin shop with /pay, /baltop and a chest-menu shop",
    "Daily quests with rewards and a quest board menu",
  ],
  sources: [
    "https://docs.papermc.io/paper/adding-plugins",
    "https://fill.papermc.io/v3/projects/paper",
  ],
  unknowns: [
    "Whether plugins compiled for 1.21.x load on Paper 26.x has not been tested here.",
    "categories: filled once the universal category set (routing agent, lib/cyrus/categories.ts) lands.",
  ],
};

export default minecraft;
