"use strict";
// Prompts for the Nxeon Mod Builder. Kept in one file so they can be reviewed
// and versioned. The orchestrator (server.js), not the model, enforces every
// rule below; the prompt only makes the model's first attempt more likely to pass.

const fs = require("fs");
const path = require("path");
const { RULES, rulesFor } = require("./precheck");

const PROMPT_VERSION = "mb-2026-10-09.1";

// Version cheat sheets (sheets/<ver>.md, every claim checked with javap against
// the Paper API jar of that version) and the reviewed failure rules. Only the
// sheet for the requested version is injected. MB_SHEETS=off / MB_RULES=off
// disable them (used by the eval to measure their effect).
const SHEETS_ON = process.env.MB_SHEETS !== "off";
const RULES_ON = process.env.MB_RULES !== "off";
const SHEETS = {};
function sheetFor(v) {
  if (!SHEETS_ON) return "";
  if (!(v in SHEETS)) {
    try { SHEETS[v] = fs.readFileSync(path.join(__dirname, "sheets", `${v}.md`), "utf8").trim(); } catch { SHEETS[v] = ""; }
  }
  return SHEETS[v];
}
function knowledgeVersion() {
  return `${SHEETS_ON ? "sheets" : "nosheets"}+${RULES_ON ? RULES.version : "norules"}`;
}

function knowledge(mcVersion) {
  const parts = [];
  const sheet = sheetFor(mcVersion);
  if (sheet) parts.push(`API REFERENCE for Paper ${mcVersion} (verified against the jar you compile with; when it disagrees with your memory, it is right):\n${sheet}`);
  const rules = RULES_ON ? rulesFor(mcVersion) : [];
  if (rules.length) parts.push(`LESSONS FROM EARLIER FAILED BUILDS (follow every one):\n${rules.map((r) => `- ${r.rule}`).join("\n")}`);
  return parts.length ? `\n\n${parts.join("\n\n")}` : "";
}

function systemPrompt(mcVersion) {
