import { isPreviewUser } from "../../preview-access";
import { db } from "../../db";
import { loadTokenConfig, type TokenConfig } from "./config";
import { effectiveTier } from "./economy";
import type { TokenTier } from "./config";

/**
 * In the token economy: the owner has launched it for everyone (cyrus_tok_live), the account is on the
 * private preview list, OR the account has EVER held tokens (an account row exists). Once an account has had
 * tokens it stays in the economy for good, even at a zero balance, so its balance stays pinned in the portal.
 */
export async function tokensActiveFor(user: { id?: string | null; email?: string | null } | null | undefined, cfg?: TokenConfig): Promise<boolean> {
  if (!user?.email) return false;
  try {
    const c = cfg ?? (await loadTokenConfig());
    if (c.live) return true;
    if (await isPreviewUser(user, "modbuilder")) return true;
    if (user.id) return !!(await db.cyrusTokenAccount.findUnique({ where: { userId: user.id }, select: { userId: true } }));
    return false;
  } catch {
    return false;
  }
}

export async function tokensActiveForUserId(userId: string, cfg?: TokenConfig): Promise<boolean> {
  const u = await db.user.findUnique({ where: { id: userId }, select: { id: true, email: true } }).catch(() => null);
  return tokensActiveFor(u, cfg);
}

/** The account's model entitlement now (plan + admin override). */
export async function tierOf(userId: string, cfg?: TokenConfig, now = new Date()): Promise<TokenTier> {
  const c = cfg ?? (await loadTokenConfig());
  const [plan, acct] = await Promise.all([
    db.cyrusPlan.findUnique({ where: { userId } }),
    db.cyrusTokenAccount.findUnique({ where: { userId }, select: { tierOverride: true, tierOverrideUntil: true } }),
  ]);
  return effectiveTier({ plan, override: acct?.tierOverride, overrideUntil: acct?.tierOverrideUntil, now, cfg: c });
}
