// Install a finished Cyrus / Mod Builder build onto one of the user's Minecraft servers.
//
// Since 2026-10-07 (Cyrus mods) this goes THROUGH THE MODS ENGINE instead of a
// direct copy: the build's chain gets a GameMod row (source "cyrus",
// lib/cyrus-mods/registry.ts), the ServerMod row is queued INSTALLING/UPDATING
// with targetVersionId = this build, and the worker's GAME_MOD_SYNC places the
// jar with lib/mods/engine.ts (state file, backup, staged write, rollback). So
// the Mods tab lists it, can switch it off/on, update it, roll it back and
// uninstall it like any other plugin.
//
// A jar a PRE-ENGINE builder install left in plugins/ (not in the engine's state
// file) is backed up to /root/.nxeon-mods/backups/<stamp>-cyrus-adopt-<name>/
// and removed first, so the server never loads two copies of one plugin.
// The route then waits briefly for the job so the Cyrus UI can say "done".
import type { ModBuild } from "@prisma/client";
import { enqueueModOp } from "../mods/queue";
import { loadState, ownerOf } from "../mods/engine";
import { ensureCyrusGameMod, loadChain, rootOf } from "../cyrus-mods/registry";
import { syncCyrusModPage } from "../cyrus-mods/pages";
import { db } from "../db";
import { SANDBOX } from "../sandbox";
import { familyFor } from "../game-config";
import { LocalGuestFs, sandboxGuestRoot, seedSandboxGuest, type GuestFs } from "../mods/guest-fs";
import { SshGuestFs } from "../../worker/mods-guest-ssh";

const MC_BASE = "/opt/mc";
const PLUGINS = `${MC_BASE}/plugins`;
const BACKUPS = "/root/.nxeon-mods/backups";
/** Generated plugins target the Paper API (Adventure etc.), so Spigot/Bukkit can't load them, and they aren't Folia-safe. */
export const MB_INSTALL_VARIANTS = ["paper", "purpur"];

export type MbServer = { id: string; name: string; variant: string | null; status: string; compatible: boolean; reason?: string };

/** The user's Minecraft servers, each marked whether a builder plugin can go on it. */
export async function modBuilderServers(userId: string): Promise<MbServer[]> {
  const rows = await db.server.findMany({
    where: { userId, status: { notIn: ["DELETING"] } },
    include: { osTemplate: true, gamePlan: true },
    orderBy: { createdAt: "asc" },
  });
  const out: MbServer[] = [];
  for (const s of rows) {
    if (familyFor(s) !== "minecraft") continue;
    const variant = (s.gameVariant || "vanilla").toLowerCase();
    const okVariant = MB_INSTALL_VARIANTS.includes(variant);
    // The engine installs onto the running server (same rule as the Mods tab).
    const okStatus = s.status === "RUNNING";
    out.push({
      id: s.id,
      name: s.label || s.hostname,
      variant,
      status: s.status,
      compatible: okVariant && okStatus,
      reason: !okVariant ? `Runs ${variant[0].toUpperCase() + variant.slice(1)}; plugins need Paper or Purpur` : !okStatus ? (s.status === "STOPPED" ? "Server is stopped — start it to install" : `Se
    });
  }
  return out;
}

function stamp(d = new Date()) {
  return d.toISOString().replace(/[-:]/g, "").replace(/\..+$/, "").replace("T", "-");
}

export type InstallResult =
  | { ok: true; path: string; replaced: string[]; backupDir: string | null; serverName: string; queued: boolean; jobId: string; modId: string }
  | { ok: false; error: string };

/**
 * Move aside jars an older (pre-engine) builder install left in plugins/: only
 * files the engine's state file does NOT own, named like this plugin. Backed up
 * first. Returns what was moved.
 */
async function adoptLegacyJars(server: Parameters<typeof SshGuestFs.open>[0] & { id: string; gameVariant: string | null }, chain: ModBuild[]): Promise<{ moved: string[]; backupDir: string | null }> {
  let fs: GuestFs;
  let ssh: SshGuestFs | null = null;
  try {
    if (SANDBOX) {
      const local = new LocalGuestFs(sandboxGuestRoot(server.id));
      await seedSandboxGuest(local, "minecraft", server.gameVariant ?? null);
      fs = local;
    } else {
      ssh = await SshGuestFs.open(server);
      fs = ssh;
    }
    if (!(await fs.stat(PLUGINS))) return { moved: [], backupDir: null };
    const state = await loadState(fs, "minecraft");
    const names = new Set(chain.map((b) => (b.pluginName ?? "").toLowerCase()).filter(Boolean));
    const jars = new Set(chain.map((b) => (b.jarName ?? "").toLowerCase()).filter(Boolean));
    const legacy = (await fs.list(PLUGINS)).filter((f) => {
      const l = f.toLowerCase();
      if (!l.endsWith(".jar") || ownerOf(state, `${PLUGINS}/${f}`)) return false;
      return jars.has(l) || [...names].some((n) => l === `${n}.jar` || (l.startsWith(`${n}-`) && /^[0-9]/.test(l.slice(n.length + 1))));
    });
    if (!legacy.length) return { moved: [], backupDir: null };
    const label = (chain[0].pluginName ?? "plugin").replace(/[^A-Za-z0-9_]/g, "") || "plugin";
    const backupDir = `${BACKUPS}/${stamp()}-cyrus-adopt-${label}`;
    for (const f of legacy) await fs.copy(`${PLUGINS}/${f}`, `${backupDir}${PLUGINS}/${f}`);
    for (const f of legacy) await fs.remove(`${PLUGINS}/${f}`);
    return { moved: legacy, backupDir };
  } finally {
    ssh?.close();
  }
}

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

export async function installBuildToServer(build: ModBuild, userId: string, serverId: string, opts: { waitMs?: number; allowPublic?: boolean } = {}): Promise<InstallResult> {
  // allowPublic (Cyrus lifecycle): install a PUBLISHED version of another creator's mod from NxLabs.
  const own = build.userId === userId;
  if (!own && !(opts.allowPublic && (await (await import("../cyrus/lifecycle/server")).publicInstallAllowed(build, userId)))) return { ok: false, error: "Not found." };
  if (build.status !== "succeeded" || !build.jarName || !build.pluginName) return { ok: false, error: "This build has no plugin file to install." };
  const server = await db.server.findUnique({ where: { id: serverId }, include: { osTemplate: true, gamePlan: true, dedicatedIp: true, node: true } });
  if (!server || server.userId !== userId) return { ok: false, error: "Server not found." };
  const servers = await modBuilderServers(userId);
  const facts = servers.find((s) => s.id === serverId);
  if (!facts) return { ok: false, error: "That server isn't a Minecraft server." };
  if (!facts.compatible) return { ok: false, error: facts.reason || "That server can't take this plugin." };
  if (!SANDBOX && process.env.ENABLE_REAL_GAMEMODS !== "1") return { ok: false, error: "One-click mod changes are paused right now, so nothing was installed." };

  const root = rootOf(build);
  const chain = await loadChain(root);
  await syncCyrusModPage(root);
  const gm = await ensureCyrusGameMod(root, chain);
  if (!gm) return { ok: false, error: "This build has no plugin file to install." };

  const existing = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
  if (existing?.status === "DISABLED") return { ok: false, error: `${gm.name} is switched off on ${facts.name}. Switch it on in the server's Mods tab first, then install this version.` };
  if (existing && !["INSTALLED", "FAILED", "REMOVED"].includes(existing.status)) return { ok: false, error: `${gm.name} is busy on that server (${existing.status.toLowerCase()}). Try again in a moment
  if (existing?.status === "INSTALLED" && existing.versionId === build.id) {
    return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: [], backupDir: null, serverName: facts.name, queued: false, jobId: "", modId: gm.id };
  }
  const op = existing?.status === "INSTALLED" ? "update" : "install";

  // First engine install on a server an older builder install already used: adopt its jar.
  let adopted: { moved: string[]; backupDir: string | null } = { moved: [], backupDir: null };
  const touched = own && chain.some((b) => (b.lastInstall as { serverId?: string } | null)?.serverId === serverId);
  if (op === "install" && touched) {
    try {
      adopted = await adoptLegacyJars(server, chain);
    } catch (e) {
      console.error("[modbuilder] legacy adopt failed", build.id, serverId, (e as Error).message);
      return { ok: false, error: "We couldn't reach the server to check its plugins folder. Check it's online and try again." };
    }
  }

  const prevVersion = existing?.status === "INSTALLED" ? existing.version : null;
  const q = await enqueueModOp(serverId, gm.id, op, { userId, slug: gm.slug }, { targetVersionId: build.id });
  if (!q.ok) return { ok: false, error: q.error };

  // Wait (briefly) for the worker so the builder UI can report the outcome.
  const deadline = Date.now() + (opts.waitMs ?? 45_000);
  while (Date.now() < deadline) {
    await sleep(1000);
    const job = await db.job.findUnique({ where: { id: q.jobId }, select: { status: true, error: true } });
    if (!job || job.status === "QUEUED" || job.status === "RUNNING") continue;
    const sm = await db.serverMod.findUnique({ where: { serverId_modId: { serverId, modId: gm.id } } });
    if (job.status === "FAILED") return { ok: false, error: sm?.error || "The install job failed. Check the server's Mods tab." };
    if (!sm || sm.status === "FAILED" || sm.versionId !== build.id) return { ok: false, error: sm?.error || "The plugin wasn't installed. Check the server's Mods tab." };
    return {
      ok: true,
      path: `${PLUGINS}/${build.jarName}`,
      replaced: [...adopted.moved, ...(prevVersion ? [`${gm.name} ${prevVersion}`] : [])],
      backupDir: adopted.backupDir,
      serverName: facts.name,
      queued: false,
      jobId: q.jobId,
      modId: gm.id,
    };
  }
  return { ok: true, path: `${PLUGINS}/${build.jarName}`, replaced: adopted.moved, backupDir: adopted.backupDir, serverName: facts.name, queued: true, jobId: q.jobId, modId: gm.id };
}

