    return { error: `${pkg.name}'s download isn't a valid jar (${e instanceof ArchiveError ? e.message : "unreadable"}) — refused.` };
  }
  if (pkg.placement === "plugin-jar" && !names.some((n) => /^(plugin|paper-plugin|bungee)\.yml$/.test(n))) {
    return { error: `${pkg.name}'s jar has no plugin.yml — it isn't a Bukkit/Paper plugin.` };
  }
  if (pkg.placement === "mod-jar" && !names.some((n) => /^(fabric\.mod\.json|quilt\.mod\.json|META-INF\/mods\.toml|META-INF\/neoforge\.mods\.toml|mcmod\.info)$/.test(n)))
    return { error: `${pkg.name}'s jar has no Fabric/Quilt/Forge mod manifest — it isn't a server mod.` };
  }
  const dir = pkg.placement === "plugin-jar" ? layout.dirs.plugins : layout.dirs.mods;
  return [{ path: joinUnder(dir, name), data: bytes }];
}

export const minecraftInstaller: FamilyInstaller = {
  family: "minecraft",
  sources: ["modrinth", "hangar", "spigotmc", CYRUS_SOURCE],
  mechanism: "Plugin jars into plugins/ (Paper/Purpur/Spigot), mod jars into mods/ (Fabric/Quilt/Forge/NeoForge), datapacks into the world's datapacks/, Modrinth modpacks
  restartRequired: true,
  compat: mcCompat,
  versionSensitive: true,
  detect: (fs, server) => detect(fs, server),
  async resolve(mod, ctx) {
    if (mod.source === "modrinth") return resolveModrinth(mod, ctx);
    if (mod.source === "hangar") return resolveHangar(mod, ctx);
    if (mod.source === "spigotmc") return resolveSpigot(mod, ctx);
    if (mod.source === CYRUS_SOURCE) return resolveCyrus(mod, ctx);
    return { error: `Minecraft one-click install doesn't support ${mod.source} yet.` };
  },
  async place(pkg, bytes, ctx) {
    if (pkg.placement === "mrpack") {
      try {
        return await placeMrpack(pkg, bytes, ctx);
      } catch (e) {
        return { error: `Couldn't unpack this modpack: ${(e as Error).message}` };
      }
    }
    return placeJarOrDatapack(pkg, bytes, ctx.layout);
  },
  legacyPaths(mod, layout) {
    // worker/game-mods.ts's pre-engine installer wrote nxeon-<slug>.jar into plugins/ or mods/.
    if (mod.source === CYRUS_SOURCE) return []; // pre-engine Cyrus installs are adopted by lib/modbuilder/install.ts
    const n = `nxeon-${mod.slug}.jar`;
    if (!/^[a-z0-9][a-z0-9._-]*$/i.test(mod.slug)) return [];
    return [`${layout.dirs.plugins}/${n}`, `${layout.dirs.mods}/${n}`];
  },
};

