};
export const TIER_LABEL: Record<TokenTier, string> = { free: "Free", katara: "Katara", saka: "Saka", all: "All models" };

export const modelsFor = (tier: TokenTier) => TIER_MODELS[tier];
export const canUseModel = (tier: TokenTier, model: CyrusModelId) => TIER_MODELS[tier].includes(model);
/** The cheapest tier that unlocks a model. */
export const tierForModel = (model: CyrusModelId): PlanTier => (model === "yakko" ? "all" : model === "saka" ? "saka" : "katara");
export const maxTier = (a: TokenTier, b: TokenTier): TokenTier => (TIER_RANK[a] >= TIER_RANK[b] ? a : b);
/** Best model a tier may use by default when the request names none. */
export const defaultModelFor = (tier: TokenTier): CyrusModelId => (canUseModel(tier, "saka") ? "saka" : "katara");
